package com.highpass.runspot.chat.config;
import com.highpass.runspot.chat.repository.ChatRoomMemberRepository;import com.highpass.runspot.common.jwt.JwtProvider;import java.security.Principal;import lombok.RequiredArgsConstructor;import org.springframework.messaging.*;import org.springframework.messaging.simp.stomp.*;import org.springframework.messaging.support.ChannelInterceptor;import org.springframework.messaging.support.MessageHeaderAccessor;import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor
public class StompHandler implements ChannelInterceptor {private final JwtProvider jwt;private final ChatRoomMemberRepository members;
 public Message<?> preSend(Message<?> message,MessageChannel channel){StompHeaderAccessor a=MessageHeaderAccessor.getAccessor(message,StompHeaderAccessor.class);if(a==null)return message;if(a.getCommand()==StompCommand.CONNECT){String value=a.getFirstNativeHeader("Authorization");if(value==null||!value.startsWith("Bearer ")||!jwt.validateToken(value.substring(7)))throw new MessagingException("유효한 JWT가 필요합니다.");a.setUser(new StompPrincipal(jwt.getUserIdFromToken(value.substring(7))));}if(a.getCommand()==StompCommand.SUBSCRIBE){Long user=id(a.getUser());String destination=a.getDestination();if(destination!=null&&destination.startsWith("/sub/chat/room/")){Long roomId=parse(destination,"/sub/chat/room/");if(members.findByRoomIdAndUserIdAndLeftAtIsNull(roomId,user).isEmpty())throw new MessagingException("채팅방 구독 권한이 없습니다.");}if(destination!=null&&destination.startsWith("/sub/chat/user/")&&!parse(destination,"/sub/chat/user/").equals(user))throw new MessagingException("개인 채널 구독 권한이 없습니다.");}return message;}
 private Long id(Principal p){if(!(p instanceof StompPrincipal s))throw new MessagingException("인증 정보가 없습니다.");return s.userId();}private Long parse(String value,String prefix){try{return Long.valueOf(value.substring(prefix.length()));}catch(Exception e){throw new MessagingException("destination 형식이 올바르지 않습니다.");}}
}
